package sigverify

import (
	"crypto/sha256"
	"encoding/hex"
	"os"
	"regexp"
	"strings"
	"testing"
)

// cli/THIRD_PARTY_NOTICES.md is generated by scripts/gen-notices.sh from the
// modules the CLI can link. It records the hashes of the files that decide
// which modules and versions those are; this test fails when any of them has
// changed since the file was generated, and when a licence is unrecognised.
// (scripts/gen-notices.sh --check does the full regeneration and diff.)
func TestThirdPartyNoticesUpToDate(t *testing.T) {
	notices, err := os.ReadFile("../../THIRD_PARTY_NOTICES.md")
	if err != nil {
		t.Fatal(err)
	}
	for _, in := range []struct{ label, path string }{
		{"cli/go.mod", "../../go.mod"},
		{"cli/go.sum", "../../go.sum"},
		{"go.work", "../../../go.work"},
	} {
		b, err := os.ReadFile(in.path)
		if err != nil {
			t.Fatal(err)
		}
		sum := sha256.Sum256(b)
		want := "- " + in.label + ": " + hex.EncodeToString(sum[:])
		if !strings.Contains(string(notices), "\n"+want+"\n") {
			t.Errorf("THIRD_PARTY_NOTICES.md is stale: %s changed; run scripts/gen-notices.sh and commit the result", in.label)
		}
	}
	if regexp.MustCompile(`(?m)^\*\*Modules with an unrecognised licence`).Match(notices) {
		t.Error("THIRD_PARTY_NOTICES.md lists modules with an unrecognised licence; a human must classify them")
	}
}
